import datetime
import json
import re
P = json.loads(PARAMS)
HOL = set(P.get('holidays') or [])
WEEKEND = set(P.get('weekend_days') if P.get('weekend_days') is not None else [5, 6])
DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MONS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def isbiz(d):
    return d.weekday() not in WEEKEND and d.isoformat() not in HOL
def say(d):
    return DAYS[d.weekday()] + ' ' + str(d.day) + ' ' + MONS[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + ONE
    while not isbiz(x):
        x = x + ONE
    return x
def nth_biz_after(d, n):
    x = d
    for i in range(n):
        x = nextbiz(x)
    return x
def get_now():
    s = str(vars.get('now') or '').strip().replace(' ', 'T')
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        return datetime.datetime.fromisoformat(s[:10] + 'T10:00')

try:
    cb = P.get('callback') or dict()
    dt = get_now()
    today = dt.date()
    hhmm = dt.strftime('%H:%M')
    lo = cb.get('from') or '00:00'
    hi = cb.get('to') or '23:59'
    lines = []
    allowed = []
    for kind in cb.get('days') or []:
        if kind == 'today':
            d = today
        elif kind == 'next_business_day':
            d = nextbiz(today)
        elif kind == 'next_day':
            d = today + ONE
        else:
            continue
        if d == today and cb.get('after_now', True) and hhmm >= lo:
            if hhmm >= hi:
                continue
            lines.append('- ' + say(d) + ' (' + d.isoformat() + '), later than ' + hhmm + ', until ' + hi + ' (included)')
        else:
            lines.append('- ' + say(d) + ' (' + d.isoformat() + '), from ' + lo + ' to ' + hi + ' (both included)')
        allowed.append(d.isoformat())
    vars['today_iso'] = today.isoformat()
    vars['today_say'] = say(today)
    vars['callback_facts'] = ('Now is ' + say(today) + ', ' + hhmm + '. "Tomorrow" is ' + say(today + ONE) + '. A callback can be booked only for:\n'
                              + '\n'.join(lines) + '\nAny other day or time is outside the window.')
    vars['callback_dates'] = ','.join(allowed)
    vars['setup_state'] = 'ok'
except Exception as e:
    vars['callback_facts'] = 'The callback window could not be computed. Do not book a callback.'
    vars['setup_state'] = 'error ' + str(e)

