        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        return datetime.datetime.fromisoformat(s[:10] + 'T10:00')

def money(x):
    x = float(x)
    if abs(x - round(x)) < 0.001:
        return str(int(round(x)))
    return '%.2f' % x
def find_products():
    p = vars.get('products')
    if isinstance(p, str):
        try:
            p = json.loads(p)
        except Exception:
            p = None
    if isinstance(p, dict) and isinstance(p.get('products'), list):
        p = p.get('products')
    if isinstance(p, list) and p:
        return p
    found = dict()
    for k in list(vars.keys()):
        m = re.search(r'products[.\[](\d+)\]?\.([a-z_0-9]+)$', str(k))
        if m:
            i = int(m.group(1))
            if i not in found:
                found[i] = dict()
            found[i][m.group(2)] = vars.get(k)
    return [found[i] for i in sorted(found)]
try:
    prods = find_products()
    p = prods[0]
    dt = get_now()
    today = dt.date()
    ptype = str(p.get('type') or '')
    past_due = float(p.get('past_due'))
    days_late = int(float(p.get('days_late')))
    if ptype == 'credit_card':
        pname = 'credit card ending ' + str(p.get('card_last4') or '')
